def chunk_text(text: str, size: int, overlap: int) -> list[str]:
    if size <= 0 or overlap < 0 or overlap >= size:
        raise ValueError("Invalid parameters")

    chunks = []
    for i in range(0, len(text), size - overlap):
        chunk = text[i:i + size]
        # Пропускаем фрагменты полностью входящие в предыдущий
        if len(chunk) == size and (i > 0 and chunk == text[i-size:i]):
            continue
        chunks.append(chunk)

    return chunks
```

